//! The licence verification public key.
//!
//! This is a **public** Ed25519 key. The matching private key is held by the release process and
//! never enters this repository, the frontend bundle or the packaged application. Rotating it means
//! shipping a new build with a new public key, which is exactly the property we want.

use base64::Engine;

/// Base64-encoded Ed25519 public key used to verify licence signatures.
///
/// Replace this with the real key generated by the release tooling before shipping. A placeholder
/// is present so the code path is exercised by the tests; the value below is a validly-shaped
/// 32-byte key and is explicitly *not* a secret.
pub const LICENSE_PUBLIC_KEY_BASE64: &str = "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=";

/// The decoded key bytes.
pub fn public_key() -> [u8; 32] {
    let mut out = [0u8; 32];
    if let Ok(bytes) = base64::engine::general_purpose::STANDARD.decode(LICENSE_PUBLIC_KEY_BASE64) {
        if bytes.len() == 32 {
            out.copy_from_slice(&bytes);
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_public_key_decodes_to_32_bytes() {
        assert_eq!(public_key().len(), 32);
    }

    #[test]
    fn the_embedded_key_is_not_a_private_key_shape() {
        // Sanity: it must decode and be a fixed length, never empty.
        assert!(!LICENSE_PUBLIC_KEY_BASE64.is_empty());
        assert_eq!(public_key().len(), 32);
    }
}
